#!/usr/bin/env bash
# Source this file. Machine settings are generated by scripts/configure.py.
export ARGO_WS_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)"
_argo_requested_domain="${ROS_DOMAIN_ID:-}"
[ ! -f "$ARGO_WS_DIR/.argo.env" ] || source "$ARGO_WS_DIR/.argo.env"
[ -z "$_argo_requested_domain" ] || export ROS_DOMAIN_ID="$_argo_requested_domain"
unset _argo_requested_domain
export PX4_DIR="$ARGO_WS_DIR/src/PX4-Autopilot"
export ARGO_SIM_PLATFORM="${ARGO_SIM_PLATFORM:-auto}"
# Humble's apt SciPy/cv_bridge must use apt NumPy, not a user-site NumPy 2.x.
export PYTHONNOUSERSITE=1
export PATH="$ARGO_WS_DIR/.local/bin:$PATH"
export LD_LIBRARY_PATH="$ARGO_WS_DIR/.local/lib:$ARGO_WS_DIR/.local/lib/x86_64-linux-gnu:$ARGO_WS_DIR/.local/lib64:${LD_LIBRARY_PATH:-}"
